style.css:
@-moz-document domain("roblox.com") {
/* Background */
html, body {
    background: linear-gradient(135deg,#05030d,#09091f,#160022) !important;
    color: #fff !important;
    font-family: "Segoe UI", sans-serif !important;
}

/* Neon glow */
* {
    border-radius: 14px !important;
    transition: .2s ease !important;
}

/* Navbar */
nav,
header,
.navbar,
.topbar,
.content,
.container-main,
#navbar,
[data-testid="navigation"]{
    background: rgba(10,10,25,.85) !important;
    border: 1px solid #00f7ff !important;
    box-shadow: 0 0 20px #00f7ff55 !important;
    backdrop-filter: blur(12px) !important;
}

/* Cards */
.game-card,
.list-item,
.card,
.section,
.content-card,
.item-card,
.profile-header,
.profile-container,
.friend-card{
    background: rgba(255,255,255,.05) !important;
    border: 1px solid #00e5ff !important;
    box-shadow: 0 0 18px #00f7ff33 !important;
}

/* Buttons */
button,
.btn-primary,
.btn-secondary,
.btn-growth-lg,
.btn-control-md,
.btn-full-width,
a.btn{
    background: linear-gradient(45deg,#00c8ff,#9500ff) !important;
    color: white !important;
    border: none !important;
    box-shadow: 0 0 18px #00f7ff !important;
    font-weight: bold !important;
}

button:hover,
.btn-primary:hover,
.btn-secondary:hover,
.btn-growth-lg:hover,
.btn-control-md:hover,
a.btn:hover{
    transform: scale(1.05) !important;
    box-shadow: 0 0 30px #ff00ff !important;
}

/* Inputs */
input,
textarea{
    background: rgba(255,255,255,.08) !important;
    color: white !important;
    border: 1px solid #00e5ff !important;
}

/* Links */
a{
    color:#00ffff !important;
    text-shadow:0 0 8px #00ffff;
}

a:hover{
    color:#ff66ff !important;
}

/* Images */
img{
    border-radius:12px !important;
}

/* Scrollbar */
::-webkit-scrollbar{
    width:12px;
}

::-webkit-scrollbar-track{
    background:#080818;
}

::-webkit-scrollbar-thumb{
    background:linear-gradient(#00ffff,#ff00ff);
    border-radius:12px;
}

/* Fake futuristic buttons (visual only) */
body::after{
    content:"? Home   ? Transfer Robux   ? AI Avatar   ? Worlds   ⚡ Trade   ? Friends   ? Play";
    position:fixed;
    bottom:20px;
    left:50%;
    transform:translateX(-50%);
    background:rgba(10,10,25,.9);
    color:#00ffff;
    padding:14px 24px;
    border:1px solid #00ffff;
    border-radius:16px;
    box-shadow:0 0 25px #00ffff;
    font-weight:bold;
    letter-spacing:.5px;
    z-index:999999;
}
}
